text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "按城市统计已完成订单销售额总和并取前两名",
      "business_question": "在只看已完成订单的前提下，各城市的销售额总和是多少？请按销售额降序排名，取前两名。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“按城市比较已完成订单的销售额总和，并降序排名取前两名”。删除此任务将无法支持该决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0003",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "top_n",
          "params": {
            "field": "total_sales",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
